namespace Aevrynd {
namespace {
struct Double3 {double x{},y{},z{};};
void SetError(MeshProcessingError3D* error,MeshProcessingErrorCode3D code,size_t index=0){if(error)*error={code,index};}
bool FiniteVertex(const Vertex3D& vertex,float maximumCoordinate){return std::isfinite(vertex.x)&&std::isfinite(vertex.y)&&std::isfinite(vertex.z)&&std::isfinite(vertex.u)&&std::isfinite(vertex.v)&&std::abs(vertex.x)<=maximumCoordinate&&std::abs(vertex.y)<=maximumCoordinate&&std::abs(vertex.z)<=maximumCoordinate;}
Double3 TriangleCross(const Vertex3D& a,const Vertex3D& b,const Vertex3D& c){const double abx=double(b.x)-a.x,aby=double(b.y)-a.y,abz=double(b.z)-a.z,acx=double(c.x)-a.x,acy=double(c.y)-a.y,acz=double(c.z)-a.z;return{aby*acz-abz*acy,abz*acx-abx*acz,abx*acy-aby*acx};}
Double3 TriangleCross(const Mesh3D& mesh,size_t offset){return TriangleCross(mesh.vertices[mesh.indices[offset]],mesh.vertices[mesh.indices[offset+1]],mesh.vertices[mesh.indices[offset+2]]);}
double LengthSquared(Double3 value){return value.x*value.x+value.y*value.y+value.z*value.z;}
double Dot(Double3 left,Double3 right){return left.x*right.x+left.y*right.y+left.z*right.z;}
bool SameDominantOrientation(Double3 source,Double3 candidate){const double x=std::abs(source.x),y=std::abs(source.y),z=std::abs(source.z);return x>=y&&x>=z?source.x*candidate.x>0:y>=z?source.y*candidate.y>0:source.z*candidate.z>0;}
double TriangleAreaSquared(const Mesh3D& mesh,size_t offset){return LengthSquared(TriangleCross(mesh,offset));}
bool AddBytes(size_t& total,size_t count,size_t element,size_t maximum){if(total>maximum||(count&&element>(maximum-total)/count))return false;total+=count*element;return true;}
bool FitsScratch(const Mesh3D& input,const MeshProcessingLimits3D& limits,size_t vertexFactor,size_t indexFactor,size_t extraPerVertex=0,size_t extraPerTriangle=0){size_t bytes{};return AddBytes(bytes,input.vertices.size(),sizeof(Vertex3D)*vertexFactor,limits.maximumScratchBytes)&&AddBytes(bytes,input.indices.size(),sizeof(uint32_t)*indexFactor,limits.maximumScratchBytes)&&AddBytes(bytes,input.vertices.size(),extraPerVertex,limits.maximumScratchBytes)&&AddBytes(bytes,input.indices.size()/3,extraPerTriangle,limits.maximumScratchBytes);}
MeshProcessingStats3D BasicStats(const Mesh3D& input,const Mesh3D& output){return{input.vertices.size(),output.vertices.size(),input.indices.size()/3,output.indices.size()/3,input.vertices.size()>output.vertices.size()?input.vertices.size()-output.vertices.size():0,input.indices.size()/3>output.indices.size()/3?input.indices.size()/3-output.indices.size()/3:0,0};}
struct VertexKey {std::array<uint32_t,7> words{};bool operator==(const VertexKey&)const=default;};
struct VertexKeyHash {size_t operator()(const VertexKey& key)const noexcept{size_t hash=1469598103934665603ull;for(uint32_t word:key.words){hash^=word;hash*=1099511628211ull;}return hash;}};
uint32_t FloatBits(float value){return std::bit_cast<uint32_t>(value==0.f?0.f:value);}
VertexKey Key(const Vertex3D& vertex){return{{FloatBits(vertex.x),FloatBits(vertex.y),FloatBits(vertex.z),vertex.normal,vertex.color,FloatBits(vertex.u),FloatBits(vertex.v)}};}
void CompactVertices(Mesh3D& mesh){std::vector<uint32_t> remap(mesh.vertices.size(),std::numeric_limits<uint32_t>::max());std::vector<Vertex3D> vertices;vertices.reserve((std::min)(mesh.vertices.size(),mesh.indices.size()));for(uint32_t& index:mesh.indices){uint32_t& mapped=remap[index];if(mapped==std::numeric_limits<uint32_t>::max()){mapped=uint32_t(vertices.size());vertices.push_back(mesh.vertices[index]);}index=mapped;}mesh.vertices=std::move(vertices);}
void RebuildSmoothNormals(Mesh3D& mesh){std::vector<Double3> sums(mesh.vertices.size());for(size_t offset=0;offset<mesh.indices.size();offset+=3){const uint32_t a=mesh.indices[offset],b=mesh.indices[offset+1],c=mesh.indices[offset+2];const Double3 weighted=TriangleCross(mesh,offset);for(uint32_t index:{a,b,c}){sums[index].x+=weighted.x;sums[index].y+=weighted.y;sums[index].z+=weighted.z;}}for(size_t index=0;index<mesh.vertices.size();++index){const Double3 sum=sums[index];const double length=std::sqrt(LengthSquared(sum));const Vec3 normal=length>1e-20?Vec3{float(sum.x/length),float(sum.y/length),float(sum.z/length)}:Vec3{};mesh.vertices[index].normal=(PackNormalSnorm8(normal)&0x00ffffffu)|(mesh.vertices[index].normal&0xff000000u);}}
struct PositionKey {uint32_t x{},y{},z{};bool operator==(const PositionKey&)const=default;};
struct PositionHash {size_t operator()(PositionKey key)const noexcept{return(size_t(key.x)*73856093u)^(size_t(key.y)*19349663u)^(size_t(key.z)*83492791u);}};
struct AttributeVariant {uint32_t u{},v{},normal{};bool operator==(const AttributeVariant&)const=default;};
struct PositionInfo {AttributeVariant first{};bool initialized{},conflicted{};};
struct ClusterKey {uint32_t x{},y{},z{},u{},v{},normal{};uint8_t semantic{};bool operator==(const ClusterKey&)const=default;};
struct ClusterHash {size_t operator()(const ClusterKey& key)const noexcept{size_t hash=(size_t(key.x)*73856093u)^(size_t(key.y)*19349663u)^(size_t(key.z)*83492791u);hash^=size_t(key.u)*2654435761u;hash^=size_t(key.v)*2246822519u;hash^=size_t(key.normal)*3266489917u;hash^=size_t(key.semantic)*668265263u;return hash;}};
struct ClusterAccumulator {double x{},y{},z{},u{},v{},r{},g{},b{},a{};size_t count{};uint8_t semantic{};};
struct TriangleKey {std::array<uint32_t,3> indices{};bool operator==(const TriangleKey&)const=default;};
struct TriangleHash {size_t operator()(const TriangleKey& key)const noexcept{return(size_t(key.indices[0])*73856093u)^(size_t(key.indices[1])*19349663u)^(size_t(key.indices[2])*83492791u);}};
bool BuildClustered(const Mesh3D& input,uint32_t resolution,Mesh3D& output){
    std::unordered_map<PositionKey,PositionInfo,PositionHash> positions;positions.reserve(input.vertices.size());for(const Vertex3D& vertex:input.vertices){const PositionKey position{FloatBits(vertex.x),FloatBits(vertex.y),FloatBits(vertex.z)};const AttributeVariant variant{FloatBits(vertex.u),FloatBits(vertex.v),vertex.normal&0x00ffffffu};PositionInfo& info=positions[position];if(!info.initialized){info.first=variant;info.initialized=true;}else if(info.first!=variant)info.conflicted=true;}
    const MeshBounds3D bounds=input.Bounds();const Vec3 minimum=bounds.center-bounds.extents,span=bounds.extents*2.f;std::unordered_map<ClusterKey,uint32_t,ClusterHash> clusters;clusters.reserve(input.vertices.size());std::vector<ClusterAccumulator> accumulators;std::vector<uint32_t> remap(input.vertices.size());for(size_t index=0;index<input.vertices.size();++index){const Vertex3D& vertex=input.vertices[index];auto cell=[&](float value,float low,float extent){if(extent<=1e-12f)return 0u;return uint32_t(Clamp((value-low)/extent,0.f,1.f)*float(resolution-1));};const PositionInfo& info=positions.at({FloatBits(vertex.x),FloatBits(vertex.y),FloatBits(vertex.z)});const uint32_t seamU=info.conflicted?FloatBits(vertex.u):0,seamV=info.conflicted?FloatBits(vertex.v):0,seamNormal=info.conflicted?(vertex.normal&0x00ffffffu):0;const uint8_t semantic=uint8_t(vertex.normal>>24);const ClusterKey key{cell(vertex.x,minimum.x,span.x),cell(vertex.y,minimum.y,span.y),cell(vertex.z,minimum.z,span.z),seamU,seamV,seamNormal,semantic};auto [iterator,inserted]=clusters.emplace(key,uint32_t(accumulators.size()));if(inserted){accumulators.emplace_back();accumulators.back().semantic=semantic;}remap[index]=iterator->second;ClusterAccumulator& accumulator=accumulators[iterator->second];const Color color=UnpackColorRgba8(vertex.color);accumulator.x+=vertex.x;accumulator.y+=vertex.y;accumulator.z+=vertex.z;accumulator.u+=vertex.u;accumulator.v+=vertex.v;accumulator.r+=color.r;accumulator.g+=color.g;accumulator.b+=color.b;accumulator.a+=color.a;++accumulator.count;}
    Mesh3D candidate;candidate.vertices.reserve(accumulators.size());for(const ClusterAccumulator& accumulator:accumulators){const float inverse=1.f/float(accumulator.count);candidate.vertices.push_back({float(accumulator.x*inverse),float(accumulator.y*inverse),float(accumulator.z*inverse),uint32_t(accumulator.semantic)<<24,PackColorRgba8({float(accumulator.r*inverse),float(accumulator.g*inverse),float(accumulator.b*inverse),float(accumulator.a*inverse)}),float(accumulator.u*inverse),float(accumulator.v*inverse)});}candidate.indices.reserve(input.indices.size());std::unordered_set<TriangleKey,TriangleHash> triangles;triangles.reserve(input.indices.size()/3);for(size_t offset=0;offset<input.indices.size();offset+=3){const uint32_t a=remap[input.indices[offset]],b=remap[input.indices[offset+1]],c=remap[input.indices[offset+2]];if(a==b||b==c||a==c)continue;const Double3 sourceNormal=TriangleCross(input,offset),candidateNormal=TriangleCross(candidate.vertices[a],candidate.vertices[b],candidate.vertices[c]);if(LengthSquared(candidateNormal)<=1e-16||Dot(sourceNormal,candidateNormal)<=0||!SameDominantOrientation(sourceNormal,candidateNormal))continue;std::array<uint32_t,3> sorted={a,b,c};std::ranges::sort(sorted);if(!triangles.insert({sorted}).second)continue;candidate.indices.insert(candidate.indices.end(),{a,b,c});}if(candidate.indices.empty())return false;CompactVertices(candidate);RebuildSmoothNormals(candidate);output=std::move(candidate);return true;}
}

bool MeshProcessing3D::Validate(const Mesh3D& input,MeshProcessingError3D* error,const MeshProcessingLimits3D& limits){if(error)*error={};if(!std::isfinite(limits.maximumAbsoluteCoordinate)||limits.maximumAbsoluteCoordinate<=0){SetError(error,MeshProcessingErrorCode3D::InvalidSetting);return false;}if(input.vertices.empty()||input.indices.empty()){SetError(error,MeshProcessingErrorCode3D::EmptyMesh);return false;}if(input.vertices.size()>limits.maximumInputVertices||input.indices.size()>limits.maximumInputIndices||input.vertices.size()>std::numeric_limits<uint32_t>::max()||input.indices.size()>std::numeric_limits<uint32_t>::max()){SetError(error,MeshProcessingErrorCode3D::LimitExceeded);return false;}if(!FitsScratch(input,limits,3,3,sizeof(PositionInfo)+sizeof(ClusterAccumulator)+sizeof(ClusterKey)+sizeof(VertexKey)+sizeof(void*)*8,sizeof(TriangleKey)+sizeof(void*)*4)){SetError(error,MeshProcessingErrorCode3D::LimitExceeded);return false;}if(input.indices.size()%3){SetError(error,MeshProcessingErrorCode3D::InvalidTriangleList,input.indices.size());return false;}for(size_t index=0;index<input.vertices.size();++index)if(!FiniteVertex(input.vertices[index],limits.maximumAbsoluteCoordinate)){SetError(error,MeshProcessingErrorCode3D::NonFiniteVertex,index);return false;}for(size_t index=0;index<input.indices.size();++index)if(input.indices[index]>=input.vertices.size()){SetError(error,MeshProcessingErrorCode3D::InvalidIndex,index);return false;}return true;}

bool MeshProcessing3D::RemoveDegenerateTriangles(const Mesh3D& input,Mesh3D& output,MeshProcessingStats3D* stats,MeshProcessingError3D* error,float areaEpsilon,const MeshProcessingLimits3D& limits){if(!Validate(input,error,limits))return false;if(!std::isfinite(areaEpsilon)||areaEpsilon<0){SetError(error,MeshProcessingErrorCode3D::InvalidSetting);return false;}Mesh3D temporary;temporary.vertices=input.vertices;temporary.indices.reserve(input.indices.size());for(size_t offset=0;offset<input.indices.size();offset+=3){const uint32_t a=input.indices[offset],b=input.indices[offset+1],c=input.indices[offset+2];if(a==b||b==c||a==c||TriangleAreaSquared(input,offset)<=areaEpsilon)continue;temporary.indices.insert(temporary.indices.end(),{a,b,c});}if(temporary.indices.empty()){SetError(error,MeshProcessingErrorCode3D::NoUsableTriangles);return false;}CompactVertices(temporary);if(temporary.vertices.size()>limits.maximumOutputVertices||temporary.indices.size()>limits.maximumOutputIndices){SetError(error,MeshProcessingErrorCode3D::LimitExceeded);return false;}MeshProcessingStats3D result=BasicStats(input,temporary);output=std::move(temporary);if(stats)*stats=result;if(error)*error={};return true;}

bool MeshProcessing3D::DeduplicateVertices(const Mesh3D& input,Mesh3D& output,MeshProcessingStats3D* stats,MeshProcessingError3D* error,const MeshProcessingLimits3D& limits){if(!Validate(input,error,limits))return false;Mesh3D temporary;temporary.vertices.reserve(input.vertices.size());temporary.indices.reserve(input.indices.size());std::unordered_map<VertexKey,uint32_t,VertexKeyHash> unique;unique.reserve(input.vertices.size());std::vector<uint32_t> remap(input.vertices.size());for(size_t index=0;index<input.vertices.size();++index){auto [iterator,inserted]=unique.emplace(Key(input.vertices[index]),uint32_t(temporary.vertices.size()));if(inserted)temporary.vertices.push_back(input.vertices[index]);remap[index]=iterator->second;}for(uint32_t index:input.indices)temporary.indices.push_back(remap[index]);if(temporary.vertices.size()>limits.maximumOutputVertices||temporary.indices.size()>limits.maximumOutputIndices){SetError(error,MeshProcessingErrorCode3D::LimitExceeded);return false;}MeshProcessingStats3D result=BasicStats(input,temporary);result.mergedVertices=input.vertices.size()-temporary.vertices.size();output=std::move(temporary);if(stats)*stats=result;if(error)*error={};return true;}

bool MeshProcessing3D::RebuildNormals(const Mesh3D& input,Mesh3D& output,MeshNormalMode3D mode,MeshProcessingStats3D* stats,MeshProcessingError3D* error,const MeshProcessingLimits3D& limits){if(!Validate(input,error,limits))return false;if(mode!=MeshNormalMode3D::AreaWeightedSmooth&&mode!=MeshNormalMode3D::HardEdges){SetError(error,MeshProcessingErrorCode3D::InvalidSetting);return false;}Mesh3D temporary;if(mode==MeshNormalMode3D::AreaWeightedSmooth){if(input.vertices.size()>limits.maximumOutputVertices||input.indices.size()>limits.maximumOutputIndices){SetError(error,MeshProcessingErrorCode3D::LimitExceeded);return false;}temporary=input;RebuildSmoothNormals(temporary);}else{if(input.indices.size()>limits.maximumOutputVertices||input.indices.size()>limits.maximumOutputIndices){SetError(error,MeshProcessingErrorCode3D::LimitExceeded);return false;}temporary.vertices.reserve(input.indices.size());temporary.indices.reserve(input.indices.size());for(size_t offset=0;offset<input.indices.size();offset+=3){const Double3 face=TriangleCross(input,offset);const double length=std::sqrt(LengthSquared(face));if(length<=1e-20)continue;const Vec3 normal{float(face.x/length),float(face.y/length),float(face.z/length)};for(size_t corner=0;corner<3;++corner){Vertex3D vertex=input.vertices[input.indices[offset+corner]];vertex.normal=(PackNormalSnorm8(normal)&0x00ffffffu)|(vertex.normal&0xff000000u);temporary.indices.push_back(uint32_t(temporary.vertices.size()));temporary.vertices.push_back(vertex);}}}if(temporary.indices.empty()){SetError(error,MeshProcessingErrorCode3D::NoUsableTriangles);return false;}MeshProcessingStats3D result=BasicStats(input,temporary);output=std::move(temporary);if(stats)*stats=result;if(error)*error={};return true;}

bool MeshProcessing3D::GenerateLod(const Mesh3D& input,Mesh3D& output,MeshLodSettings3D settings,MeshProcessingStats3D* stats,MeshProcessingError3D* error,const MeshProcessingLimits3D& limits){if(!Validate(input,error,limits))return false;if(!std::isfinite(settings.targetTriangleRatio)||settings.targetTriangleRatio<=0||settings.targetTriangleRatio>=1||settings.maximumGridResolution<2||settings.maximumGridResolution>4096){SetError(error,MeshProcessingErrorCode3D::InvalidSetting);return false;}const size_t inputTriangles=input.indices.size()/3,target=(std::max)(size_t{1},size_t(std::floor(double(inputTriangles)*settings.targetTriangleRatio)));Mesh3D best;size_t bestDifference=std::numeric_limits<size_t>::max();for(uint32_t resolution=settings.maximumGridResolution;;resolution=(std::max)(2u,resolution*3/4)){Mesh3D candidate;if(BuildClustered(input,resolution,candidate)&&candidate.vertices.size()<=limits.maximumOutputVertices&&candidate.indices.size()<=limits.maximumOutputIndices&&candidate.indices.size()/3<inputTriangles){const size_t triangles=candidate.indices.size()/3,difference=triangles>target?triangles-target:target-triangles;if(difference<bestDifference){bestDifference=difference;best=std::move(candidate);}if(triangles<=target)break;}if(resolution==2)break;}if(best.indices.empty()){SetError(error,MeshProcessingErrorCode3D::NoUsableTriangles);return false;}MeshProcessingStats3D result=BasicStats(input,best);result.mergedVertices=input.vertices.size()>best.vertices.size()?input.vertices.size()-best.vertices.size():0;output=std::move(best);if(stats)*stats=result;if(error)*error={};return true;}

bool MeshProcessing3D::ReorderForVertexCache(const Mesh3D& input,Mesh3D& output,uint32_t cacheSize,MeshProcessingStats3D* stats,MeshProcessingError3D* error,const MeshProcessingLimits3D& limits){if(!Validate(input,error,limits))return false;if(cacheSize<3||cacheSize>256){SetError(error,MeshProcessingErrorCode3D::InvalidSetting);return false;}if(input.vertices.size()>limits.maximumOutputVertices||input.indices.size()>limits.maximumOutputIndices){SetError(error,MeshProcessingErrorCode3D::LimitExceeded);return false;}const size_t triangleCount=input.indices.size()/3;std::vector<std::vector<uint32_t>> adjacency(input.vertices.size());for(uint32_t triangle=0;triangle<triangleCount;++triangle)for(size_t corner=0;corner<3;++corner)adjacency[input.indices[size_t(triangle)*3+corner]].push_back(triangle);std::vector<uint8_t> emitted(triangleCount),queued(triangleCount);std::deque<uint32_t> queue;std::vector<uint32_t> cache;cache.reserve(cacheSize);Mesh3D temporary;temporary.vertices=input.vertices;temporary.indices.reserve(input.indices.size());size_t emittedCount{},fallback{};auto enqueue=[&](uint32_t vertex){for(uint32_t triangle:adjacency[vertex])if(!emitted[triangle]&&!queued[triangle]){queued[triangle]=1;queue.push_back(triangle);}};while(emittedCount<triangleCount){uint32_t triangle=std::numeric_limits<uint32_t>::max();while(!queue.empty()){const uint32_t candidate=queue.front();queue.pop_front();queued[candidate]=0;if(!emitted[candidate]){triangle=candidate;break;}}if(triangle==std::numeric_limits<uint32_t>::max()){while(fallback<triangleCount&&emitted[fallback])++fallback;triangle=uint32_t(fallback);}emitted[triangle]=1;++emittedCount;const size_t offset=size_t(triangle)*3;for(size_t corner=0;corner<3;++corner)temporary.indices.push_back(input.indices[offset+corner]);for(size_t corner=0;corner<3;++corner){const uint32_t vertex=input.indices[offset+corner];const bool entered=std::find(cache.begin(),cache.end(),vertex)==cache.end();cache.erase(std::remove(cache.begin(),cache.end(),vertex),cache.end());cache.insert(cache.begin(),vertex);if(cache.size()>cacheSize)cache.pop_back();if(entered)enqueue(vertex);}}MeshProcessingStats3D result=BasicStats(input,temporary);output=std::move(temporary);if(stats)*stats=result;if(error)*error={};return true;}
}
